    log(`[backfill] OpenCode DB not found at ${opencodeDbPath} \u2014 marking all unbackfilled sessions as skipped. Lazy adoption (defense-in-depth) handles legacy rows at runtime.`);
    markAllUnbackfilledSessionsSkipped(db);
